def edit_view(self) -> T_RESPONSE | str:
    """
    Edit model view
    """
    return_url = get_redirect_target() or self.get_url(".index_view")

    if not self.can_edit:
        return redirect(return_url)

    id = get_mdict_item_or_list(request.args, "id")
    if id is None:
        return redirect(return_url)

    model = self.get_one(id)

    if model is None:
        flash(gettext("Record does not exist."), "error")
        return redirect(return_url)
    form = self.edit_form(obj=model)
    if not hasattr(form, "_validated_ruleset") or not form._validated_ruleset:
        self._validate_form_instance(ruleset=self._form_edit_rules, form=form)

    if self.validate_form(form):
        if self.update_model(form, model):
            flash(gettext("Record was successfully saved."), "success")
            if "_add_another" in request.form:
                return redirect(self.get_url(".create_view", url=return_url))
            elif "_continue_editing" in request.form:
                return redirect(
                    self.get_url(
                        ".edit_view", id=self.get_pk_value(model), url=return_url
                    )
                )
            else:
                # save button
                return redirect(self.get_save_return_url(model, is_created=False))
    else:
        if is_form_submitted():
            flash(gettext("Failed to save record."), "danger")

    if request.method == "GET" or form.errors:
        self.on_form_prefill(form, id)

    form_opts = FormOpts(
        widget_args=self.form_widget_args, form_rules=self._form_edit_rules
    )

    if self.edit_modal and request.args.get("modal"):
        template = self.edit_modal_template
    else:
        template = self.edit_template

    return self.render(
        template, model=model, form=form, form_opts=form_opts, return_url=return_url
    )

